return ['domain'=>'zinn-cache','plural-forms'=>'nplurals=2; plural=(n != 1 && n != 2 && n != 3 && (n%10 == 4 || n%10 == 6 || n%10 == 9));','language'=>'tl','project-id-version'=>'zinn-cache','pot-creation-date'=>'2026-09-02T07:33:02+00:00','po-revision-date'=>'2026-09-02T07:33:02+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache'=>'Zinn® Cache','https://zinndigital.com/wordpress-plugins/zinn-cache'=>'https://zinndigital.com/wordpress-plugins/zinn-cache','For sites hosted with Zinn Digital®. Controls the page cache your Zinn® server already provides — smart auto-purge on content change, remote purge from your Zinn® dashboard, a Redis object-cache toggle, safe WordPress/WooCommerce exclusions, and one-click admin login. This is a cache controller, not a cache engine. Hosting elsewhere? Install Zinn® Cache Engine instead.'=>'Para sa mga site na naka-host sa Zinn Digital®. Kinokontrol ang page cache na ibinibigay na ng iyong Zinn® server — smart auto-purge sa pagbabago ng nilalaman, remote purge mula sa iyong Zinn® dashboard, isang Redis object-cache toggle, ligtas na mga pagbubukod sa WordPress/WooCommerce, at one-click admin login. Isa itong cache controller, hindi cache engine. Nag-a-host sa iba? I-install ang Zinn® Cache Engine sa halip.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','You are not allowed to purge the cache.'=>'Hindi ka pinapayagang i-purge ang cache.','Cache purge requested.'=>'Hiniling ang pag-cache purge.','Zinn® Cache: another object-cache drop-in is installed, so the Redis object cache is not managed by this plugin.'=>'Zinn® Cache: naka-install ang isa pang object-cache drop-in, kaya ang Redis object cache ay hindi pinamamahalaan ng plugin na ito.','Full-page cache (LiteSpeed)'=>'Buong-pahinang cache (LiteSpeed)','Enable LSCache control'=>'Paganahin ang kontrol ng LSCache','Send LiteSpeed cache-control and tag headers on cacheable pages.'=>'Magpadala ng LiteSpeed cache-control at tag headers sa mga pahinang maaaring i-cache.','Public cache lifetime (seconds)'=>'Habang-buhay ng pampublikong cache (mga segundo)','Object cache (Redis)'=>'Cache ng object (Redis)','Enable Redis object cache'=>'Pagana ang Redis object cache','Install the Redis object-cache drop-in (requires the phpredis extension).'=>'I-install ang Redis object-cache drop-in (nangangailangan ng phpredis extension).','Redis host'=>'Host ng Redis','Redis port'=>'Redis port','Redis database'=>'Database ng Redis','Redis key prefix'=>'Prefix ng Redis key','Automatic purging'=>'Awtomatikong paglilinis','Smart auto-purge'=>'Matalinong awtomatikong pag-purge','Purge affected pages automatically when content changes.'=>'Awtomatikong i-purge ang mga apektadong pahina kapag nagbago ang nilalaman.','Purge on updates'=>'Linisin sa mga pag-update','Purge everything after core, plugin, or theme updates.'=>'I-purge ang lahat pagkatapos ng mga update ng core, plugin, o tema.','Cache exclusions'=>'Mga pagbubukod sa cache','Sensible WordPress and WooCommerce defaults are always applied (cart, checkout, my-account, logged-in and session pages are never cached). Add extra rules below, one per line.'=>'Palaging inilalapat ang mga makatwirang default ng WordPress at WooCommerce (ang cart, checkout, my-account, logged-in at mga pahina ng session ay hindi kailanman kino-cache). Magdagdag ng mga karagdagang panuntunan sa ibaba, isa bawat linya.','Exclude URL paths (prefix match)'=>'Iba-excel ang mga landas ng URL (tugma ng unlapi)','Exclude query keys'=>'Ibig-exclude ang mga query key','Exclude cookie name prefixes'=>'Huwag isama ang mga prefix ng pangalan ng cookie','Maintenance'=>'Pagpapanatili','Purge everything now'=>'Burahin ang lahat ngayon','detected'=>'natagpuan','not detected'=>'hindi nakita','phpredis extension missing'=>'nawawala ang phpredis extension','active'=>'aktibo','inactive'=>'hindi aktibo','LiteSpeed cache:'=>'LiteSpeed cache:','Redis object cache:'=>'Cache ng object ng Redis:','The Redis PHP extension (phpredis) is not available on this server, so the object cache cannot be enabled.'=>'Hindi available ang Redis PHP extension (phpredis) sa server na ito, kaya hindi paganahin ang object cache.','Another object-cache drop-in is already installed. Remove it before enabling the Zinn® object cache.'=>'May nakalagay nang ibang object-cache drop-in. Alisin ito bago paganahin ang Zinn® object cache.','Could not write the Redis connection configuration file.'=>'Hindi maisulat ang file ng pagsasaayos ng koneksyon sa Redis.','The bundled object-cache drop-in could not be read.'=>'Hindi mabasa ang naka-bundle na object-cache drop-in.','Could not install the object-cache drop-in into wp-content.'=>'Hindi ma-install ang object-cache drop-in sa wp-content.','Could not remove the object-cache drop-in.'=>'Hindi naalis ang object-cache drop-in.','The WordPress filesystem is not writable, so the object-cache drop-in could not be managed.'=>'Hindi maisusulat ang WordPress filesystem, kaya hindi mapamahalaan ang object-cache drop-in.','This one-click login link is not valid any more. Links expire after a couple of minutes and can only be used once — open your site from the Zinn® dashboard again to get a fresh one.'=>'Hindi na balido ang link sa pag-login na ito sa isang click. Nag-e-expire ang mga link pagkalipas ng ilang minuto at minsan lang magagamit — buksan ulit ang iyong site mula sa Zinn® dashboard para kumuha ng bago.','See the Zinn Digital® release notes.'=>'Tingnan ang mga tala sa pagpapalabas ng Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Nabigo ang nai-download na update sa pagsusuri ng integridad nito at hindi na-install.','%s — guides and services'=>'%s — mga gabay at serbisyo','User guides'=>'Mga gabay sa gumagamit','Read the %s user guide'=>'Basahin ang %s gabay sa gumagamit','Hide this'=>'Itago ito','Zinn® hosting for WordPress'=>'Hosting ng Zinn® para sa WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, araw-araw na backup, libreng migrasyon at control panel na ginawa para sa mga taong nagpapatakbo ng higit sa isang site.','The Zinn® marketplace'=>'Ang pamilihan ng Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Bumili at magbenta ng mga naitatag nang site, domain, at paglalagay ng link, na ang pera ay ligtas na nakatago hanggang sa parehong panig ay masiyahan.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — umarkila ng mga taong ito ang ikinabubuhay','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Ang aming pandaigdigang pamilihan para sa mga freelancer: mag-browse ng mahigit 10,000 handang serbisyo mula sa mga manunulat, taga-disenyo, developer, at SEO, o mag-post ng proyekto at hayaan silang mag-bid.']];